const payload = $input.first().json || {};

// البيانات الأساسية
const request = payload;

const user = payload.user || {};

const activeSession =
  payload.active_session ||
  payload.session ||
  {};

const input =
  payload.input ||
  {};

const text = (input.text || '').trim();
const action = input.button_action || '';
const currentStep = activeSession.current_step || 'full_name';

// ===============================
// Direct PDF Generation Route
// ===============================
if (action === 'GENERATE_CV_PDF') {
  return [
    {
      json: {
        request,
        user,
        active_session: activeSession,

        route_to_pdf: true,

        update_session: 0,
        needs_structuring: 0,

        session_update: {},

        response: {
          ok: true,
          status: 'completed',
          reply: {
            type: 'text',
            text: '📄 جاري تجهيز ملف PDF...',
            buttons: [],
            file: null
          },
          data: {},
          error: null
        }
      }
    }
  ];
}

// تحميل Context الجلسة
let context = {};
try {
  if (activeSession.context_json) {
    context =
      typeof activeSession.context_json === 'string'
        ? JSON.parse(activeSession.context_json)
        : activeSession.context_json;
  }
} catch (e) {
  context = {};
}
function controlButtons() {
  return [
    { label: '🏠 القائمة الرئيسية', action: 'MAIN_MENU' },
    { label: '❌ إلغاء', action: 'CANCEL' }
  ];
}

function reviewButtons() {
  return [
    { label: '✅ تأكيد وإنشاء CV', action: 'CONFIRM_CREATE_CV' },
    { label: '✏️ تعديل البيانات', action: 'EDIT_CREATE_CV_DATA' },
    { label: '🏠 القائمة الرئيسية', action: 'MAIN_MENU' },
    { label: '❌ إلغاء', action: 'CANCEL' }
  ];
}

function buildResponse(message, nextStep, status = 'active', buttons = null) {
  return {
    ok: true,
    status:
      status === 'waiting_for_confirmation'
        ? 'waiting_for_confirmation'
        : 'in_progress',
    reply: {
      type: 'text',
      text: message,
      buttons: buttons || controlButtons(),
      file: null
    },
    session_update: {
      active_service: 'CREATE_CV',
      current_step: nextStep,
      status,
      context_json: context
    },
    data: {},
    error: null
  };
}

let nextStep = currentStep;
let status = 'active';
let responseText = '';
let updateSession = true;
let responseButtons = null;

if (currentStep === 'full_name') {
  if (!text || text.length < 3) {
    updateSession = false;
    responseText = 'اكتب اسمك الكامل بشكل أوضح، مثال: محمد أحمد البزور';

    return [
      {
        json: {
          request,
          user,
          active_session: activeSession,
          update_session: 0,
          needs_structuring: 0,
          session_update: {},
          response: buildResponse(responseText, currentStep, status)
        }
      }
    ];
  }

  context.full_name = text;
  nextStep = 'contact_info';

  responseText =
`ممتاز يا ${text}.

الآن اكتب معلومات التواصل التي تريد إظهارها في السيرة الذاتية.

مثال:
رقم الهاتف، البريد الإلكتروني، المدينة، LinkedIn أو GitHub إن وجد.`;
}

else if (currentStep === 'contact_info') {
  if (!text || text.length < 5) {
    updateSession = false;
    responseText =
`اكتب معلومات التواصل بشكل أوضح.

مثال:
0790000000
email@example.com
Amman, Jordan
linkedin.com/in/username`;

    return [
      {
        json: {
          request,
          user,
          active_session: activeSession,
          update_session: 0,
          needs_structuring: 0,
          session_update: {},
          response: buildResponse(responseText, currentStep, status)
        }
      }
    ];
  }

  context.contact_info = text;
  nextStep = 'target_role';

  responseText =
`تمام.

ما هو المسمى الوظيفي أو الدور الذي تستهدفه في السيرة الذاتية؟

مثال:
Frontend Developer
Backend Developer
Data Analyst
Graphic Designer`;
}

else if (currentStep === 'target_role') {
  if (!text || text.length < 2) {
    updateSession = false;
    responseText = 'اكتب المسمى الوظيفي المستهدف، مثل: Frontend Developer';

    return [
      {
        json: {
          request,
          user,
          active_session: activeSession,
          update_session: 0,
          needs_structuring: 0,
          session_update: {},
          response: buildResponse(responseText, currentStep, status)
        }
      }
    ];
  }

  context.target_role = text;
  nextStep = 'summary';

  responseText =
`ممتاز.

اكتب نبذة قصيرة عنك أو عن خبرتك المهنية.

مثال:
مطور ويب مهتم ببناء واجهات استخدام سريعة وتجربة مستخدم ممتازة.

إذا لا تريد كتابة نبذة الآن، اكتب: تخطي`;
}

else if (currentStep === 'summary') {
  if (text === 'تخطي' || text.toLowerCase() === 'skip') {
    context.summary = '';
  } else {
    context.summary = text;
  }

  nextStep = 'experience';

  responseText =
`الآن اكتب خبراتك العملية.

اكتبها بهذا الشكل مثلًا:
- الشركة:
- المسمى الوظيفي:
- المدة:
- أهم المهام والإنجازات:

إذا لا توجد خبرة، اكتب: تخطي`;
}

else if (currentStep === 'experience') {
  if (text === 'تخطي' || text.toLowerCase() === 'skip') {
    context.experience = [];
  } else {
    context.experience_text = text;
  }

  nextStep = 'education';

  responseText =
`اكتب معلومات التعليم.

مثال:
- الجامعة أو المؤسسة:
- التخصص:
- الدرجة:
- سنة التخرج:

إذا لا تريد إضافتها، اكتب: تخطي`;
}

else if (currentStep === 'education') {
  if (text === 'تخطي' || text.toLowerCase() === 'skip') {
    context.education = [];
  } else {
    context.education_text = text;
  }

  nextStep = 'skills';

  responseText =
`اكتب المهارات الخاصة بك.

مثال:
JavaScript, React, Node.js, SQL, Git

أو اكتبها كسطور منفصلة.`;
}

else if (currentStep === 'skills') {
  if (!text || text.length < 2) {
    updateSession = false;
    responseText = 'اكتب بعض المهارات، مثال: JavaScript, React, SQL';

    return [
      {
        json: {
          request,
          user,
          active_session: activeSession,
          update_session: 0,
          needs_structuring: 0,
          session_update: {},
          response: buildResponse(responseText, currentStep, status)
        }
      }
    ];
  }

  context.skills_text = text;
  nextStep = 'projects';

  responseText =
`اكتب أهم المشاريع التي عملت عليها.

مثال:
- اسم المشروع:
- وصف مختصر:
- التقنيات المستخدمة:
- رابط المشروع إن وجد:

إذا لا تريد إضافة مشاريع، اكتب: تخطي`;
}

else if (currentStep === 'projects') {
  if (text === 'تخطي' || text.toLowerCase() === 'skip') {
    context.projects = [];
  } else {
    context.projects_text = text;
  }

  nextStep = 'certifications';

  responseText =
`هل لديك شهادات أو دورات؟

اكتبها مثل:
- اسم الشهادة:
- الجهة:
- السنة:

إذا لا يوجد، اكتب: تخطي`;
}

else if (currentStep === 'certifications') {
  if (text === 'تخطي' || text.toLowerCase() === 'skip') {
    context.certifications = [];
  } else {
    context.certifications_text = text;
  }

  nextStep = 'languages';

  responseText =
`اكتب اللغات التي تتقنها.

مثال:
العربية: ممتاز
الإنجليزية: جيد جدًا`;
}

else if (currentStep === 'languages') {
  if (!text || text.length < 2) {
    updateSession = false;
    responseText = 'اكتب اللغات، مثال: العربية ممتاز، الإنجليزية جيد جدًا';

    return [
      {
        json: {
          request,
          user,
          active_session: activeSession,
          update_session: 0,
          needs_structuring: 0,
          session_update: {},
          response: buildResponse(responseText, currentStep, status)
        }
      }
    ];
  }

  context.languages_text = text;
  nextStep = 'review';
  status = 'waiting_for_confirmation';
  responseButtons = reviewButtons();

  responseText =
`ممتاز. هذه البيانات التي جمعناها:

الاسم: ${context.full_name || '-'}
التواصل: ${context.contact_info || '-'}
المسمى المستهدف: ${context.target_role || '-'}
النبذة: ${context.summary || '-'}
الخبرات: ${context.experience_text || 'لا يوجد'}
التعليم: ${context.education_text || 'لا يوجد'}
المهارات: ${context.skills_text || '-'}
المشاريع: ${context.projects_text || 'لا يوجد'}
الشهادات: ${context.certifications_text || 'لا يوجد'}
اللغات: ${context.languages_text || '-'}

إذا البيانات صحيحة اضغط تأكيد، أو اختر تعديل البيانات.`;
}

else if (currentStep === 'review') {
  if (action === 'CONFIRM_CREATE_CV') {
    context.confirmed = true;
    context.confirmed_at = new Date().toISOString();
    context.needs_structuring = true;

    nextStep = 'generate';
    status = 'active';

    responseText =
`تمام. تم تأكيد البيانات ✅

جاري تنظيم بيانات السيرة الذاتية وتجهيزها للملف...`;
  }

  else if (action === 'EDIT_CREATE_CV_DATA') {
    nextStep = 'edit_request';
    status = 'active';

    responseText =
`تمام. اكتب التعديل المطلوب بوضوح.

مثال:
غيّر المسمى الوظيفي إلى Frontend Developer
أو:
عدّل رقم الهاتف إلى +962...`;
  }

  else {
    updateSession = false;
    responseButtons = reviewButtons();

    responseText =
`أنت في مرحلة مراجعة البيانات.

اضغط "✅ تأكيد وإنشاء CV" للمتابعة، أو "✏️ تعديل البيانات" لتعديل أي معلومة.`;

    return [
      {
        json: {
          request,
          user,
          active_session: activeSession,
          update_session: 0,
          needs_structuring: 0,
          session_update: {},
          response: buildResponse(responseText, currentStep, status, responseButtons)
        }
      }
    ];
  }
}

else if (currentStep === 'edit_request') {
  if (!text || text.length < 3) {
    updateSession = false;

    responseText =
`اكتب التعديل المطلوب بشكل أوضح.

مثال:
غيّر رقم الهاتف إلى +962...
أو:
عدّل المسمى الوظيفي إلى React Developer`;

    return [
      {
        json: {
          request,
          user,
          active_session: activeSession,
          update_session: 0,
          needs_structuring: 0,
          session_update: {},
          response: buildResponse(responseText, currentStep, status)
        }
      }
    ];
  }

  context.pending_edit_request = text;

  nextStep = 'review';
  status = 'waiting_for_confirmation';
  responseButtons = reviewButtons();

  responseText =
`تم استلام طلب التعديل.

حاليًا سنضيف لاحقًا AI Edit Interpreter لتطبيق التعديل تلقائيًا.

طلبك:
${text}

ارجع للمراجعة واضغط تأكيد عند الجاهزية.`;
}

else if (currentStep === 'generate') {
  updateSession = false;

  responseText =
`وصلنا لمرحلة توليد السيرة الذاتية.

الخطوة القادمة:
1. تنظيم البيانات إلى JSON
2. حفظها في قاعدة البيانات
3. توليد ملف PDF`;

  return [
    {
      json: {
        request,
        user,
        active_session: activeSession,
        update_session: 0,
        needs_structuring: 0,
        session_update: {},
        response: buildResponse(responseText, currentStep, status, [
          { label: '🏠 القائمة الرئيسية', action: 'MAIN_MENU' }
        ])
      }
    }
  ];
}

else {
  updateSession = false;
  responseText =
`حدث خطأ في خطوة إنشاء CV الحالية: ${currentStep}

اضغط القائمة الرئيسية وابدأ من جديد.`;
}

const contextJsonString = JSON.stringify(context);

const sessionUpdate = {
  current_step: nextStep,
  status,
  context_json: context,
  context_json_string: contextJsonString,
  last_message_type: input.type || 'text'
};

const needsStructuring = context.needs_structuring ? 1 : 0;

return [
  {
    json: {
      request,
      user,
      active_session: activeSession,
      update_session: updateSession ? 1 : 0,
      needs_structuring: needsStructuring,
      session_update: sessionUpdate,
      response: buildResponse(responseText, nextStep, status, responseButtons)
    }
  }
];

const input = $("Process Create CV Step").first().json;
const response = input.response;

return [
  {
    json: {
      ok: response?.ok ?? true,
      status: response?.status || 'in_progress',
      request: input.request,
      user: input.user,
      active_session: input.active_session,
      response,
      reply: response?.reply || null,
      data: response?.data || {},
      error: response?.error || null
    }
  }
];

const input = $("Process Create CV Step").first().json;
const response = input.response;

return [
  {
    json: {
      ok: response?.ok ?? true,
      status: response?.status || 'in_progress',
      request: input.request,
      user: input.user,
      active_session: input.active_session,
      response,
      reply: response?.reply || null,
      data: response?.data || {},
      error: response?.error || null
    }
  }
];

const payload = $input.first().json;

const request = payload.request || {};
const user = payload.user || {};
const activeSession = payload.active_session || {};

// المصدر الحقيقي للبيانات
const context =
  activeSession.context_json ||
  payload.context ||
  payload.session_context ||
  {};

function valueOrEmpty(value) {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.join('\n');
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

const rawCvData = {
  full_name: valueOrEmpty(context.full_name),
  contact_info: valueOrEmpty(context.contact_info),
  target_role: valueOrEmpty(context.target_role),
  summary: valueOrEmpty(context.summary),
  experience_text: valueOrEmpty(context.experience_text),
  education_text: valueOrEmpty(context.education_text),
  skills_text: valueOrEmpty(context.skills_text),
  projects_text: valueOrEmpty(context.projects_text),
  certifications_text: valueOrEmpty(context.certifications_text),
  languages_text: valueOrEmpty(context.languages_text)
};

const aiInput = {
  task: 'structure_cv',
  language: request?.context?.language || 'en',
  output_language: 'en',

  instructions: {
    goal: 'Convert raw CV data into clean structured ATS-friendly CV JSON.',
    rules: [
      'Return valid JSON only.',
      'Do not include markdown.',
      'Do not wrap output in code fences.',
      'Do not invent companies, dates, degrees, emails, phone numbers, or links.',
      'If a field is missing, use an empty string or empty array.',
      'Keep content professional and ATS-friendly.',
      'Improve wording lightly, but preserve the user meaning.',
      'Split skills into clear arrays.',
      'Parse contact info into email, phone, location, links when possible.',
      'Parse experience into separate objects when possible.',
      'Parse education into separate objects when possible.',
      'Parse projects into separate objects when possible.',
      'Parse certifications into separate objects when possible.',
      'Parse languages into separate objects when possible.'
    ]
  },

  raw_cv_data: rawCvData,

  required_schema: {
    personal: {
      full_name: '',
      target_role: '',
      email: '',
      phone: '',
      location: '',
      links: {
        linkedin: '',
        github: '',
        portfolio: '',
        other: []
      }
    },

    summary: '',

    experience: [
      {
        title: '',
        company: '',
        location: '',
        start_date: '',
        end_date: '',
        is_current: false,
        bullets: []
      }
    ],

    education: [
      {
        institution: '',
        degree: '',
        field: '',
        location: '',
        graduation_year: '',
        details: ''
      }
    ],

    skills: {
      technical: [],
      tools: [],
      soft: [],
      other: []
    },

    projects: [
      {
        name: '',
        description: '',
        technologies: [],
        link: '',
        bullets: []
      }
    ],

    certifications: [
      {
        name: '',
        issuer: '',
        year: '',
        link: ''
      }
    ],

    languages: [
      {
        language: '',
        level: ''
      }
    ],

    metadata: {
      source: 'create_cv',
      template: 'modern',
      language: 'en'
    }
  }
};

return [
  {
    json: {
      request,
      user,
      active_session: activeSession,
      context,
      raw_cv_data: rawCvData,
      ai_input: aiInput,

      // للتأكد من البيانات قبل إرسالها للـ AI
      debug: {
        extracted_full_name: rawCvData.full_name,
        extracted_target_role: rawCvData.target_role,
        extracted_summary: rawCvData.summary
      },

      ai_prompt: JSON.stringify(aiInput, null, 2)
    }
  }
];

const source = $('Prepare AI Input').first().json;
const aiResponse = $input.first().json;

// تنظيف رد AI
const rawText = String(aiResponse.output || '')
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let cvJson;

try {
  cvJson = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    'Invalid JSON returned by AI:\n' +
    rawText.substring(0, 2000)
  );
}

return [
  {
    json: {
      user_id: source.user.id,
      session_id: source.active_session.id,

      service: 'create_cv_from_scratch',
      status: 'completed',
      language: cvJson?.metadata?.language || 'en',

      cv_json: cvJson,

      cv_text: '',
      ats_notes_json: {},
      missing_required_fields_json: [],
      missing_optional_fields_json: [],

      // احتفظ به إذا كنت تحتاج Debugging
      ai_raw_output: rawText
    }
  }
];

const original = $('Process Create CV Step').first().json;
const parsed = $('Parse AI CV JSON').first().json;

return [
  {
    json: {
      chat_id: original.request.meta.chat_id,
      user_id: original.user.id,

      cv_json: parsed.cv_json,

      response: {
        ok: true,
        status: 'completed',

        reply: {
          type: 'text',
          text: `✅ تم إنشاء السيرة الذاتية بنجاح

👤 ${parsed.cv_json.personal?.full_name || '-'}
💼 ${parsed.cv_json.personal?.target_role || '-'}

راجع السيرة الذاتية ثم اضغط "توليد PDF".`,
          buttons: [
            {
              label: '📄 توليد PDF',
              action: 'GENERATE_CV_PDF'
            },
            {
              label: '🏠 القائمة الرئيسية',
              action: 'MAIN_MENU'
            }
          ]
        },

        session_update: {
          active_service: 'CREATE_CV',
          current_step: 'document_generation',
          status: 'active',

          context_json: {
            cv_json: parsed.cv_json
          }
        }
      }
    }
  }
];

const original = $('Process Create CV Step').first().json;

return [{
  json: {
    ...$json,
    chat_id: original.request.meta.chat_id
  },
  binary: $binary
}];
